const P = () => window.Plates;
const esc = (s) => String(s == null ? '' : s).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const inr = (x, d = 2) => '₹' + Number(x).toLocaleString('en-IN', { minimumFractionDigits: d, maximumFractionDigits: d });
const pct = (x) => Math.round(100 * x) + '%';
const short = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const ctl = (el, html) => { const d = document.createElement('div'); d.className = 'ctl'; d.innerHTML = html; el.appendChild(d); return d; };
const pick = (c, attr, fn) => c.addEventListener('click', (e) => { const b = e.target.closest('button'); if (!b) return; e.stopPropagation(); c.querySelectorAll('button').forEach((x) => x.classList.toggle('on', x === b)); fn(b.dataset[attr]); });
const R = (tag) => (L6.runs || {})[tag];
const GATE_T = { supplier_not_found: 'Onboard supplier', centre_closed: 'Fix cost centre', food_contact_no_cert: 'Ask for certificate', over_limit: 'Approval' };
const MET = { asked_missing: 'asked for the missing field', no_lookup_asks: 'never asked what it can look up', no_forbidden: 'no forbidden tool', no_duplicate: 'no duplicate write', final_status: 'right final status', right_clause: 'right clause cited', NE1: 'NE1 no approver', NE2: 'NE2 duplicate order', NE3: 'NE3 no certificate', NE4: 'NE4 duplicate supplier', NE5: 'NE5 done, not released' };
const MSHORT = { asked_missing: 'asked', no_lookup_asks: 'no lookup', no_forbidden: 'forbidden', no_duplicate: 'duplicate', final_status: 'status', right_clause: 'clause', NE1: 'NE1', NE2: 'NE2', NE3: 'NE3', NE4: 'NE4', NE5: 'NE5' };
const AG = { naive: 'naive · 38 raw services', loop: 'tool loop · intent tools', graph: 'control graph' };
const COL = { naive: 'var(--before)', loop: 'var(--gold)', graph: 'var(--after)' };

/* A conversation as chat bubbles; marks: {turnIndex: html} drawn beside an agent message. */
const thread = (turns, opts = {}) => turns.map((t, i) => `<div class="msg u" style="font-size:${opts.fs || 16}px;padding:6px 12px"><div class="who">Kavita${t.act && t.act !== 'open' ? ' · ' + esc(t.act) : ''}</div>${esc(short(t.user, opts.un || 220))}</div>
  <div class="msg ag" style="font-size:${opts.fs || 16}px;white-space:pre-wrap;padding:6px 12px"><div class="who">agent${t.writes && t.writes.length ? ' · writes ' + esc(t.writes.join(', ')) : ''}</div>${esc(short(t.agent, opts.an || 420))}${opts.marks && opts.marks[i] ? `<div style="margin-top:6px">${opts.marks[i]}</div>` : ''}</div>`).join('');

