/* ---------- Fig: the suite derived from the control graph: 16 gate combinations, then the rest ---------- */
FIGS.suitegen = (el) => {
  const S = L6.suite; if (!S) { el.innerHTML = '<i>no suite</i>'; return { step() {} }; }
  const W = 1400, H = 500, E = P().svgEl, T = P().txt;
  const svg = E('svg', { viewBox: `0 0 ${W} ${H}`, width: W, height: H }, el);
  const gates = S.gates, cx0 = 400, cw = 60, ry0 = 40, rh = 40;
  gates.forEach((g, r) => T(svg, cx0 - 16, ry0 + r * rh + 30, GATE_T[g] || g, 'font:20px var(--serif);fill:var(--ink-2)', 'end'));
  const cells = [], heads = [];
  S.combinations.forEach((c, i) => {
    const x = cx0 + i * cw;
    heads.push(T(svg, x + cw / 2 - 4, ry0 - 14, 'G' + String(i).padStart(2, '0'), 'font:600 14px var(--mono);fill:var(--ink-3)', 'middle'));
    gates.forEach((g, r) => { const on = c.gates.includes(g); cells.push({ i, on, n: E('rect', { x: x + 4, y: ry0 + r * rh + 6, width: cw - 14, height: rh - 12, rx: 3, style: `fill:${on ? 'var(--after)' : 'var(--paper-2)'};opacity:0.08;transition:opacity .4s` }, svg) }); });
  });
  const fam = [['V', 'variants of each gate', 13], ['A', 'adversarial · one per never-event', 9], ['M', 'asks: left out, changed, refused', 9], ['N', 'answer-only, write nothing', 7], ['S', 'the six course scenarios', 6]];
  const rows = fam.map(([f, lab, n], k) => {
    const y = 250 + k * 44, g = E('g', { style: 'opacity:0;transition:opacity .5s' }, svg);
    T(g, cx0 - 16, y + 25, `${f} · ${lab}`, 'font:19px var(--serif);fill:var(--ink-2)', 'end');
    const ids = S.cases.filter((c) => c.family === f);
    ids.forEach((c, j) => { const r = E('rect', { x: cx0 + j * 66 + 4, y: y + 4, width: 58, height: 32, rx: 3, style: `fill:${c.kind === 'adversarial' ? 'var(--before)' : c.kind === 'negative' ? 'var(--gold)' : 'var(--after)'};opacity:.85;cursor:pointer` }, g);
      const t = T(g, cx0 + j * 66 + 33, y + 26, c.id, 'font:600 14px var(--mono);fill:#fff;pointer-events:none', 'middle');
      r.addEventListener('click', (e) => { e.stopPropagation(); info.textContent = `${c.id} · ${c.name} · ${c.kind}${c.gates.length ? ' · gates: ' + c.gates.map((x) => GATE_T[x]).join(' + ') : ''}${c.tempts.length ? ' · tempts ' + c.tempts.join(', ') : ''}${c.must_ask.length ? ' · must ask: ' + c.must_ask.join(', ') : ''} · expects: ${c.expect}`; }); void t; });
    return g;
  });
  const total = T(svg, cx0 + 4, 240, '', 'font:600 18px var(--mono);fill:var(--ink)');
  const info = T(svg, 1390, 240, 'Click a case.', 'font:17px var(--serif);fill:var(--ink-2)', 'end');
  S.combinations.forEach((c, i) => { const hit = E('rect', { x: cx0 + i * cw, y: ry0 - 34, width: cw - 6, height: rh * 4 + 40, style: 'fill:transparent;cursor:pointer' }, svg);
    hit.addEventListener('click', (e) => { e.stopPropagation(); const cs = S.cases.find((x) => x.id === 'G' + String(i).padStart(2, '0')); info.textContent = cs ? `${cs.id} · ${cs.name} · opens: ${cs.gates.map((x) => GATE_T[x]).join(' + ') || 'nothing'} · expects: ${cs.expect}` : ''; }); });
  return { step(k) {
    const shown = k === 0 ? 1 : k === 1 ? 16 : 16;
    cells.forEach((c) => (c.n.style.opacity = c.i < shown ? (c.on ? 1 : 0.6) : 0.08));
    rows.forEach((g, j) => (g.style.opacity = k >= 2 + Math.min(j, 0) && k >= 2 ? (k >= 3 || j < 2 ? 1 : 0.15) : 0));
    total.textContent = k >= 3 ? `${S.cases.length} cases · suite hash ${S.hash}` : k >= 1 ? '16 gate combinations' : '';
  } };
};

