  const bars = sp.map((s) => { const r = E('rect', { x: X(s.start), y: 40 + s.turn * 70, width: Math.max(2, X(s.start + s.seconds) - X(s.start) - 1), height: 34, style: `fill:${colr[s.purpose] || 'var(--ink-3)'};opacity:0;transition:opacity .3s` }, svg);
    const tt = E('title', {}, r); tt.textContent = `${s.node} · ${s.purpose} · ${s.seconds}s · ${s.tokens_in}+${s.tokens_out} tokens · ₹${s.inr}`; return r; });
  [0, Math.round(end / 2), Math.round(end)].forEach((v) => Tx(svg, X(v), 270, v + ' s', 'font:14px var(--mono);fill:var(--ink-3)', 'middle'));
  const lab = Tx(svg, 40, 305, '', 'font:17px var(--serif);fill:var(--ink-2)');
  const tot = sp.reduce((a, s) => a + s.seconds, 0), tin = sp.reduce((a, s) => a + s.tokens_in + s.tokens_out, 0), ci = sp.reduce((a, s) => a + s.inr, 0);
  const box = document.createElement('div'); el.appendChild(box);
  const ts = L6.turn_seconds || {};
  const hist = (tag) => { const xs = ts[tag] || []; if (!xs.length) return ''; const p = (q) => xs[Math.max(1, Math.ceil(q * xs.length)) - 1];
    const mx = Math.max(...xs), bins = 24, cnt = Array(bins).fill(0); xs.forEach((x) => cnt[Math.min(bins - 1, Math.floor(x / mx * bins))]++); const cm = Math.max(...cnt);
    return `<svg viewBox="0 0 960 170" width="960" height="170">${cnt.map((c, i) => `<rect x="${120 + i * 33}" y="${120 - 100 * c / cm}" width="30" height="${100 * c / cm}" style="fill:${COL[tag]};opacity:.75"></rect>`).join('')}
      <line x1="${120 + 792 * p(0.5) / mx}" x2="${120 + 792 * p(0.5) / mx}" y1="10" y2="125" style="stroke:var(--ink);stroke-dasharray:4 4"></line><text x="${124 + 792 * p(0.5) / mx}" y="22" style="font:15px var(--mono)">p50 ${p(0.5)} s</text>
      <line x1="${120 + 792 * p(0.95) / mx}" x2="${120 + 792 * p(0.95) / mx}" y1="10" y2="125" style="stroke:var(--before);stroke-width:3"></line><text x="${124 + 792 * p(0.95) / mx}" y="44" style="font:600 15px var(--mono);fill:var(--before)">p95 ${p(0.95)} s</text>
      <text x="110" y="120" text-anchor="end" style="font:15px var(--mono);fill:var(--ink-2)">${tag}</text><text x="120" y="150" style="font:14px var(--mono);fill:var(--ink-3)">0 s</text><text x="912" y="150" text-anchor="end" style="font:14px var(--mono);fill:var(--ink-3)">${mx} s · ${xs.length} turns</text></svg>`; };
  let tag = 'graph';
